// Every method of ITaskSchedulerService returns an HRESULT ([MS-TSCH] 3.2.5,
// [MS-ERREF] section 2.1). The HRESULT values themselves are not declared here: the
// whole of [MS-ERREF] 2.1.1 lives in
// github.com/TheManticoreProject/Manticore/windows/errors/hresult as the HRESULT
// type, and a subset repeated here would cover a fraction of that 2928-value table
// while drifting from it. Convert a returned status with hresult.HRESULT(status) and
// test it with hresult.HRESULT.IsSuccess, which reads a range rather than a value:
// bit 31 clear is success, so S_OK, S_FALSE and every SCHED_S_* informational code
// satisfy it.
//
// The three codes below are the exception. WinError.h defines SCHED_E_TASK_DISABLED,
// SCHED_E_TASK_NOT_V1_COMPAT and SCHED_E_START_ON_DEMAND, but the [MS-ERREF] 2.1.1
// SCHED_* block ends at SCHED_E_TASK_ATTEMPTED (0x80041324) and names none of the
// three, so the shared table cannot decode them and renders them as hex. These stay
// declared here and StatusString decodes them before deferring to the shared table
// for everything else.
const (
	SchedETaskDisabled    uint32 = 0x80041326 // SCHED_E_TASK_DISABLED
	SchedETaskNotV1Compat uint32 = 0x80041327 // SCHED_E_TASK_NOT_V1_COMPAT
	SchedEStartOnDemand   uint32 = 0x80041328 // SCHED_E_START_ON_DEMAND
)

