// StatusString names the three Task Scheduler HRESULTs WinError.h defines and
// [MS-ERREF] 2.1.1 omits, and defers every other status to the shared [MS-ERREF]
// 2.1.1 table, which names each value the specification defines, derives a name for
// the FACILITY_WIN32 values it wraps, and renders hex only for values it does not
// define.
func StatusString(status uint32) string {
	switch status {
	case SchedETaskDisabled:
		return "SCHED_E_TASK_DISABLED"
	case SchedETaskNotV1Compat:
		return "SCHED_E_TASK_NOT_V1_COMPAT"
	case SchedEStartOnDemand:
		return "SCHED_E_START_ON_DEMAND"
	default:
		return hresult.HRESULT(status).String()
	}
}

